/* 考研专区渲染 */
"use strict";
(function () {
  document.addEventListener("DOMContentLoaded", () => {
    const K = SITE_DATA.kaoyan;
    const E = K.exam408;

    document.getElementById("ky-408-desc").innerHTML =
      `试卷满分 ${E.full_score} 分，考试时间 ${E.duration_min} 分钟。内容结构：` +
      E.subjects.map(s => `${s.name} ${s.score} 分`).join("、") +
      `。题型：${E.question_structure}。大纲来源：<a href="${E.syllabus_source.source_url}" target="_blank" rel="noopener">${E.syllabus_source.source_platform}</a>（verified_at ${E.syllabus_source.verified_at}）。`;

    /* 408 四门子科目：大纲章节骨架 */
    const grid = document.getElementById("ky-408-grid");
    E.subjects.forEach(s => {
      const card = h("div", { class: "course-card", id: `course-${s.code}` });
      card.innerHTML = `
        <div class="cc-head"><span class="badge kaoyan">408</span><span class="badge code">${s.score} 分</span></div>
        <div class="cc-name">${s.name}</div>
        <div class="cc-status"><span class="badge ok">大纲骨架 ${s.chapters.length} 章</span></div>
        <details class="chapters" ${s.code === "408-ds" ? "open" : ""}>
          <summary>展开大纲章节与子知识点</summary>
          <ul class="chapter-list">
            ${s.chapters.map(ch => `<li><strong>${ch.title}</strong>${ch.subs.length ? `<ul class="chapter-list" style="margin:4px 0 0;">${ch.subs.map(x => `<li style="font-size:13px;">${x}</li>`).join("")}</ul>` : ""}</li>`).join("")}
          </ul>
        </details>`;
      grid.appendChild(card);
    });

    /* 数二 */
    document.getElementById("ky-math2").innerHTML = `
      <h3>数学（二）· 满分 ${K.math2.score} 分</h3>
      <ul style="font-size:14.5px;line-height:2;margin-top:8px;">
        ${K.math2.scope.map(x => `<li>${x}</li>`).join("")}
      </ul>
      <div class="notice info">${K.math2.note}</div>
      <p class="src">来源：<a href="${K.math2.source_url}" target="_blank" rel="noopener">中国研究生招生信息网 · 考研大纲栏目</a> · verified_at ${K.math2.verified_at}</p>`;

    /* 英二 */
    document.getElementById("ky-eng2").innerHTML = `
      <h3>英语（二）· 满分 ${K.eng2.score} 分</h3>
      <ul style="font-size:14.5px;line-height:2;margin-top:8px;">
        ${K.eng2.structure.map(x => `<li>${x}</li>`).join("")}
      </ul>
      <div class="notice info">${K.eng2.note}</div>
      <p class="src">来源：<a href="${K.eng2.source_url}" target="_blank" rel="noopener">中国研究生招生信息网 · 考研大纲栏目</a> · verified_at ${K.eng2.verified_at}</p>`;

    /* 真题 */
    const pp = document.getElementById("ky-papers");
    if (K.papers.length === 0) {
      pp.innerHTML = `<div class="notice empty">暂无已收录真题。</div>`;
    } else {
      pp.innerHTML = K.papers.map(p => `
        <div class="card" style="margin-bottom:14px;">
          <h3>${p.title} <span class="badge kaoyan">kaoyan</span></h3>
          <p class="muted">来源平台：${p.source_platform} · 来源类型：原始试卷（重排版） · 收录快照：${p.crawled_at}</p>
          <p style="font-size:13.5px;margin-top:6px;">${p.note}</p>
          <p class="src" style="margin-top:8px;">完整 URL：<a href="${p.source_url}" target="_blank" rel="noopener">${p.source_url}</a></p>
        </div>`).join("") +
        `<div class="notice empty">数二 / 英二的公开真题以回忆版为主，本站按“回忆版显著标注、无原始出处不收录”的标准执行；当前未收录数二 / 英二题目。</div>`;
    }
  });
})();
